  zone_id    = "023e105f4ecef8ad9ca31a8372d0c353"
  setting_id = "ciphers"
  value = [
    "ECDHE-ECDSA-AES128-GCM-SHA256",
    "ECDHE-ECDSA-CHACHA20-POLY1305"
  ]
}

# Nested object value
